// Parity of the C++ capital / xVA kernels with Python and Rust on the shared
// fixture rust/core/tests/data/xva_capital_parity.txt (generated by
// python -m qp_core.xva._parity), plus the BCBS 279 Example 1 end to end.
#include <gtest/gtest.h>

#include <cmath>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

#include "qp/xva.hpp"

namespace x = qp::xva;

namespace {

void close(double got, double want, const std::string& what) {
    const double tol = 1e-13 * std::max(std::abs(want), 1e-2);
    EXPECT_LE(std::abs(got - want), tol) << what << " got " << got << " want " << want;
}

std::vector<double> vec(std::istringstream& in, std::size_t n) {
    std::vector<double> v(n);
    for (auto& e : v) in >> e;
    return v;
}

}  // namespace

TEST(XvaCapital, MatchesPythonFixture) {
    std::ifstream file(QP_XVA_FIXTURE);
    ASSERT_TRUE(file.good()) << QP_XVA_FIXTURE;
    std::string line;
    int seen = 0;
    while (std::getline(file, line)) {
        if (line.empty() || line[0] == '#') continue;
        if (line.back() == '\r') line.pop_back();
        std::istringstream in(line);
        std::string kind;
        in >> kind;
        if (kind == "SD") {
            double s, e, w;
            in >> s >> e >> w;
            close(x::saccr_supervisory_duration(s, e), w, line);
        } else if (kind == "DELTA") {
            double p, k, v, t, sh, w;
            int c, b;
            in >> p >> k >> v >> t >> c >> b >> sh >> w;
            close(x::saccr_supervisory_delta(p, k, v, t, c == 1, b == 1, sh), w, line);
        } else if (kind == "MF") {
            double m, mp, w;
            in >> m >> mp >> w;
            close(x::saccr_maturity_factor(m, mp >= 0.0 ? std::optional<double>(mp) : std::nullopt), w, line);
        } else if (kind == "MULT") {
            double v, c, a, w;
            in >> v >> c >> a >> w;
            close(x::saccr_multiplier(v, c, a), w, line);
        } else if (kind == "IREN") {
            double a, b, c, w;
            in >> a >> b >> c >> w;
            close(x::saccr_ir_effective_notional(a, b, c), w, line);
        } else if (kind == "SFA") {
            std::size_t n;
            in >> n;
            const auto a = vec(in, n), r = vec(in, n);
            double w;
            in >> w;
            close(x::saccr_single_factor_addon(a, r), w, line);
        } else if (kind == "ZBO") {
            double a, s, t, sm, pt, ps, k, w;
            int c;
            in >> a >> s >> t >> sm >> pt >> ps >> k >> c >> w;
            close(x::HullWhite(a, s).zcb_option(t, sm, pt, ps, k, c == 1), w, line);
        } else if (kind == "SWPT") {
            double a, s, t0, p0, k, w;
            std::size_t n;
            int payer;
            in >> a >> s >> t0 >> p0 >> n;
            const auto pay = vec(in, n), pp = vec(in, n), acc = vec(in, n);
            in >> k >> payer >> w;
            close(x::HullWhite(a, s).swaption(t0, p0, pay, pp, acc, k, payer == 1), w, line);
        } else if (kind == "XVA") {
            std::size_t m;
            in >> m;
            const auto t = vec(in, m), ee = vec(in, m), ene = vec(in, m);
            const auto hct = vec(in, 2), hch = vec(in, 2), hbt = vec(in, 1), hbh = vec(in, 1);
            double c1, c2, fca, fba;
            in >> c1 >> c2 >> fca >> fba;
            const x::Hazard hc{hct, hch}, hb{hbt, hbh};
            close(x::default_leg(t, ee, hc, 0.4), c1, "cva");
            close(x::default_leg(t, ee, hc, 0.4, &hb), c2, "cva bilateral");
            const auto [f, b] = x::fva(t, ee, ene, 0.01, 0.004, hc, hb);
            close(f, fca, "fca");
            close(b, fba, "fba");
        } else if (kind == "EEPE") {
            std::size_t m;
            in >> m;
            const auto t = vec(in, m), ee = vec(in, m);
            double mat, w;
            in >> mat >> w;
            close(x::eepe(t, ee, mat), w, line);
        } else if (kind == "PFE") {
            std::size_t n, w;
            double q;
            in >> n >> q >> w;
            EXPECT_EQ(x::pfe_index(n, q), w) << line;
        } else if (kind == "GRHO") {
            double a, b, w;
            int same;
            in >> a >> b >> same >> w;
            close(x::sbm_girr_delta_rho(a, b, same == 1), w, line);
        } else if (kind == "SCEN") {
            double rho, w;
            int sc;
            in >> rho >> sc >> w;
            close(x::sbm_scenario_corr(rho, sc), w, line);
        } else if (kind == "KB") {
            std::size_t n;
            in >> n;
            const auto ws = vec(in, n), rho = vec(in, n * n);
            double w;
            in >> w;
            close(x::sbm_within_bucket(ws, rho), w, line);
        } else if (kind == "ACROSS") {
            std::size_t n;
            in >> n;
            const auto k = vec(in, n), s = vec(in, n);
            double g, w;
            in >> g >> w;
            close(x::sbm_across_buckets(k, s, g), w, line);
        } else {
            FAIL() << "unknown record " << kind;
        }
        ++seen;
    }
    EXPECT_EQ(seen, 83);
}

TEST(XvaCapital, BcbsExample1EndToEnd) {
    // BCBS 279 Annex 4a Example 1: add-on 347, EAD 569 thousand.
    const double delta = x::saccr_supervisory_delta(0.06, 0.05, 0.5, 1.0, false, true);
    const double usd = x::saccr_ir_effective_notional(0.0, -10000.0 * x::saccr_supervisory_duration(0.0, 4.0),
                                                      10000.0 * x::saccr_supervisory_duration(0.0, 10.0));
    const double eur = x::saccr_ir_effective_notional(0.0, 0.0, delta * 5000.0 * x::saccr_supervisory_duration(1.0, 11.0));
    const double addon = 0.005 * (usd + eur);
    const double ead = 1.4 * (60.0 + x::saccr_multiplier(60.0, 0.0, addon) * addon);
    EXPECT_EQ(std::round(addon), 347.0);
    EXPECT_EQ(std::round(ead), 569.0);
}

TEST(XvaCapital, RejectsBadInput) {
    EXPECT_THROW((void)x::saccr_supervisory_duration(5.0, 1.0), std::invalid_argument);
    EXPECT_THROW(x::HullWhite(0.0, 0.01), std::invalid_argument);
    EXPECT_THROW((void)x::pfe_index(0, 0.5), std::invalid_argument);
}
